def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([2, 1]), fmt([1, 2]), fmt([3, 3, 3]), fmt([-10**9, 10**9, 0]), fmt([10**9, -10**9]),
             fmt([5, 1, 5, 1, 5]), fmt([9, 8, 7, 6, 5, 4, 3, 2, 1])]
    for n in (3, 4, 6, 8, 10, 15):
        for _ in range(2):
            hi = rng.choice([3, 10, 1000])
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt(list(range(N, 0, -1))))
    tests.append(fmt([rng.randint(-5, 5) for _ in range(N)]))
    tests.append(fmt([7] * N))
    return tests
